import "../css/BuyNow.css";
export default function BuyNow(props) {
    return (
        <div className="buyNowContainer">
            <h2>Buy Now</h2>
            <p>Price: ₹{props.price}</p>
            <button className="buyNowButton">Proceed to Buy</button>
        </div>
    );
}
